/**
 * Tests for server-side wallet signature verification.
 *
 * Every signature in here is generated by the real signing primitives at
 * run time (secp256k1 / ed25519), so the suite proves the exact operations the
 * `web3-auth` function performs on a live request — recovery, low-s
 * normalisation, address derivation and strict RFC 8032 verification — rather
 * than a canned fixture that could drift from the implementation.
 */

import {
  hashEthereumPersonalMessage,
  normalizeEthereumAddress,
  normalizeSolanaAddress,
  recoverEthereumAddress,
  verifyEthereumSignature,
  verifySolanaSignature,
  Web3VerificationError,
} from "./web3-verify.ts";
import { assertEquals, assertThrows } from "jsr:@std/assert@1";
import { secp256k1 } from "https://esm.sh/@noble/curves@1.9.7/secp256k1";
import { ed25519 } from "https://esm.sh/@noble/curves@1.9.7/ed25519";
import { keccak_256 } from "https://esm.sh/@noble/hashes@1.8.0/sha3";
import { base58 } from "https://esm.sh/@scure/base@2.4.0";

const encoder = new TextEncoder();

function hex(bytes: Uint8Array): string {
  return Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
}

function fromHex(value: string): Uint8Array {
  const clean = value.startsWith("0x") ? value.slice(2) : value;
  const out = new Uint8Array(clean.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = parseInt(clean.slice(i * 2, i * 2 + 2), 16);
  }
  return out;
}

function toBase64(bytes: Uint8Array): string {
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary);
}

// secp256k1 group order, used to malleate signatures deliberately.
const N = 0xfffffffffffffffffffffffffffffffebaaedce6af48a03bbfd25e8cd0364141n;

// Deterministic Ethereum key (a scalar far below N, therefore valid).
const ETH_PRIV = new Uint8Array(32).fill(1);
const ETH_MESSAGE = "example.com wants you to sign in with your Ethereum account:\n0x0000000000000000000000000000000000000000";

function ethAddressOf(privKey: Uint8Array): string {
  const pub = secp256k1.getPublicKey(privKey, false);
  return `0x${hex(keccak_256(pub.subarray(1)).subarray(12))}`;
}

const ETH_ADDRESS = ethAddressOf(ETH_PRIV);

/** Sign `message` the way an EIP-191 wallet does, returning r||s||v hex. */
function signEthereum(message: string, vStyle: "27" | "0" | "eip155" = "27"): string {
  const digest = hashEthereumPersonalMessage(message);
  const signature = secp256k1.sign(digest, ETH_PRIV, { prehash: false });
  const recovery = signature.recovery ?? 0;
  const v = vStyle === "27"
    ? recovery + 27
    : vStyle === "0"
      ? recovery
      : 35 + recovery; // EIP-155 with chainId 1: 2 * 1 + 35 + recovery
  return `0x${hex(signature.toCompactRawBytes())}${v.toString(16).padStart(2, "0")}`;
}

function expectVerificationError(fn: () => unknown, code: string): void {
  const error = assertThrows(fn, Web3VerificationError) as Web3VerificationError;
  assertEquals(error.code, code);
}

// ── Ethereum hashing ─────────────────────────────────────────────────────────

Deno.test("hashEthereumPersonalMessage matches independently computed EIP-191 digests", () => {
  // Vectors cross-checked against two unrelated implementations — ethers.js
  // `hashMessage` and `js-sha3` keccak256 — computed over the raw prefixed
  // bytes. Cases cover empty input, ASCII, multi-byte characters (byte length
  // ≠ char length) and long input (two-digit length prefixes).
  const vectors: Array<[string, string]> = [
    ["", "5f35dce98ba4fba25530a026ed80b2cecdaa31091ba4958b99b52ea1d068adad"],
    ["hello", "50b2c43fd39106bafbba0da34fc430e1f91e3c96ea2acee2bc34119f92b37750"],
    [
      "example.com wants you to sign in with your Ethereum account: ✓ ünïcode",
      "116865214159689f87f40929b385b2523af8dbd0b0a2cc69cdb66478fb2711d3",
    ],
    ["x".repeat(70), "8eff3e3b35e3eddf63e0db4a278bedef3c7f94f951795ac67b6206749120146c"],
    [
      "Sitesurveyor sign-in nonce 12345678",
      "d9905af020d022b929b31cacee53caa0247af00ad31a59078f32c4b95f04f2de",
    ],
  ];

  for (const [message, expected] of vectors) {
    assertEquals(hex(hashEthereumPersonalMessage(message)), expected);
  }
});

Deno.test("hashEthereumPersonalMessage is stable and message-length sensitive", () => {
  const one = hex(hashEthereumPersonalMessage("hello"));
  const two = hex(hashEthereumPersonalMessage("hellp"));
  assertEquals(one, hex(hashEthereumPersonalMessage("hello")));
  assertEquals(one === two, false);
});

// ── Ethereum address handling ────────────────────────────────────────────────

Deno.test("normalizeEthereumAddress lower-cases valid addresses", () => {
  assertEquals(
    normalizeEthereumAddress("0x52908400098527886E0F7030069857D2E4169EE7"),
    "0x52908400098527886e0f7030069857d2e4169ee7",
  );
});

Deno.test("normalizeEthereumAddress rejects malformed addresses", () => {
  for (const bad of [
    "0x123",
    "52908400098527886E0F7030069857D2E4169EE7", // no 0x prefix
    "0xZZ908400098527886E0F7030069857D2E4169EE7", // non-hex
    "0x52908400098527886e0f7030069857d2e4169ee7ff", // too long
    "",
  ]) {
    expectVerificationError(() => normalizeEthereumAddress(bad), "INVALID_ADDRESS");
  }
});

// ── Ethereum signature verification ──────────────────────────────────────────

Deno.test("verifyEthereumSignature accepts a correctly signed message (v = 27/28)", () => {
  const signature = signEthereum(ETH_MESSAGE, "27");
  const result = verifyEthereumSignature({
    message: ETH_MESSAGE,
    signature,
    expectedAddress: ETH_ADDRESS,
  });
  assertEquals(result.address, ETH_ADDRESS.toLowerCase());
});

Deno.test("verifyEthereumSignature accepts wallets that return v = 0/1", () => {
  const signature = signEthereum(ETH_MESSAGE, "0");
  const result = verifyEthereumSignature({
    message: ETH_MESSAGE,
    signature,
    expectedAddress: ETH_ADDRESS.toUpperCase().replace("0X", "0x"),
  });
  assertEquals(result.address, ETH_ADDRESS.toLowerCase());
});

Deno.test("verifyEthereumSignature accepts EIP-155 encoded v values", () => {
  const signature = signEthereum(ETH_MESSAGE, "eip155");
  const result = verifyEthereumSignature({
    message: ETH_MESSAGE,
    signature,
    expectedAddress: ETH_ADDRESS,
  });
  assertEquals(result.address, ETH_ADDRESS.toLowerCase());
});

Deno.test("verifyEthereumSignature survives deliberate s-malleation (low-s normalisation)", () => {
  const digest = hashEthereumPersonalMessage(ETH_MESSAGE);
  const signature = secp256k1.sign(digest, ETH_PRIV, { prehash: false });
  const compact = signature.toCompactRawBytes();

  const s = BigInt(`0x${hex(compact.subarray(32, 64))}`);
  const malleatedS = N - s;
  const malleatedRecovery = (signature.recovery ?? 0) ^ 1;

  const evilSig =
    hex(compact.subarray(0, 32)) +
    hex(fromHex(`0x${malleatedS.toString(16).padStart(64, "0")}`)) +
    (malleatedRecovery + 27).toString(16).padStart(2, "0");
  // The malleated signature still verifies and still resolves to the owner.
  const asHex = `0x${evilSig}`;
  assertEquals(recoverEthereumAddress(ETH_MESSAGE, asHex), ETH_ADDRESS.toLowerCase());
  assertEquals(
    verifyEthereumSignature({
      message: ETH_MESSAGE,
      signature: asHex,
      expectedAddress: ETH_ADDRESS,
    }).address,
    ETH_ADDRESS.toLowerCase(),
  );
});

Deno.test("verifyEthereumSignature rejects a signature over a different message", () => {
  const signature = signEthereum(ETH_MESSAGE);
  expectVerificationError(
    () =>
      verifyEthereumSignature({
        message: `${ETH_MESSAGE}!`,
        signature,
        expectedAddress: ETH_ADDRESS,
      }),
    "SIGNATURE_MISMATCH",
  );
});

Deno.test("verifyEthereumSignature rejects a signature from another wallet", () => {
  const signature = signEthereum(ETH_MESSAGE);
  const stranger = ethAddressOf(new Uint8Array(32).fill(2));
  expectVerificationError(
    () =>
      verifyEthereumSignature({
        message: ETH_MESSAGE,
        signature,
        expectedAddress: stranger,
      }),
    "SIGNATURE_MISMATCH",
  );
});

Deno.test("verifyEthereumSignature rejects truncated or malformed encodings", () => {
  expectVerificationError(
    () =>
      verifyEthereumSignature({
        message: ETH_MESSAGE,
        signature: `0x${"ab".repeat(64)}`, // 64 bytes: r and s, no v
        expectedAddress: ETH_ADDRESS,
      }),
    "INVALID_SIGNATURE_ENCODING",
  );
  expectVerificationError(
    () =>
      verifyEthereumSignature({
        message: ETH_MESSAGE,
        signature: "0xabc", // odd-length hex
        expectedAddress: ETH_ADDRESS,
      }),
    "INVALID_SIGNATURE_ENCODING",
  );
});

Deno.test("verifyEthereumSignature rejects an unrecognised recovery id", () => {
  const digest = hashEthereumPersonalMessage(ETH_MESSAGE);
  const compact = secp256k1.sign(digest, ETH_PRIV, { prehash: false }).toCompactRawBytes();
  expectVerificationError(
    () =>
      verifyEthereumSignature({
        message: ETH_MESSAGE,
        signature: `0x${hex(compact)}05`, // v = 5 is not 0/1/27/28/EIP-155
        expectedAddress: ETH_ADDRESS,
      }),
    "INVALID_SIGNATURE",
  );
});

Deno.test("verifyEthereumSignature rejects out-of-range scalars", () => {
  const digest = hashEthereumPersonalMessage(ETH_MESSAGE);
  const compact = secp256k1.sign(digest, ETH_PRIV, { prehash: false }).toCompactRawBytes();
  const badS = "ff".repeat(32);
  expectVerificationError(
    () =>
      verifyEthereumSignature({
        message: ETH_MESSAGE,
        signature: `0x${hex(compact.subarray(0, 32))}${badS}1b`,
        expectedAddress: ETH_ADDRESS,
      }),
    "INVALID_SIGNATURE",
  );
});

// ── Solana address handling ──────────────────────────────────────────────────

const SOL_PRIV = new Uint8Array(32).fill(7);
const SOL_PUB = ed25519.getPublicKey(SOL_PRIV);
const SOL_ADDRESS = base58.encode(SOL_PUB);
const SOL_MESSAGE = "example.com wants you to sign in with your Solana account:\nanything";

function signSolana(message: string): Uint8Array {
  return ed25519.sign(encoder.encode(message), SOL_PRIV);
}

Deno.test("normalizeSolanaAddress accepts a canonical base58 public key", () => {
  assertEquals(normalizeSolanaAddress(SOL_ADDRESS), SOL_ADDRESS);
});

Deno.test("normalizeSolanaAddress rejects malformed addresses", () => {
  for (const bad of [
    `${SOL_ADDRESS.slice(0, -1)}0`, // '0' is not in the base58 alphabet
    `${SOL_ADDRESS.slice(0, -1)}l`, // 'l' is not in the base58 alphabet
    base58.encode(new Uint8Array(31).fill(7)), // 31 bytes
    base58.encode(new Uint8Array(33).fill(7)), // 33 bytes
    "",
    "not base58 !!",
  ]) {
    expectVerificationError(() => normalizeSolanaAddress(bad), "INVALID_ADDRESS");
  }
});

// ── Solana signature verification ────────────────────────────────────────────

Deno.test("verifySolanaSignature accepts a base58 encoded signature", () => {
  const result = verifySolanaSignature({
    message: SOL_MESSAGE,
    signature: base58.encode(signSolana(SOL_MESSAGE)),
    expectedAddress: SOL_ADDRESS,
  });
  assertEquals(result.address, SOL_ADDRESS);
});

Deno.test("verifySolanaSignature accepts a base64 encoded signature", () => {
  const result = verifySolanaSignature({
    message: SOL_MESSAGE,
    signature: toBase64(signSolana(SOL_MESSAGE)),
    expectedAddress: SOL_ADDRESS,
  });
  assertEquals(result.address, SOL_ADDRESS);
});

Deno.test("verifySolanaSignature rejects a signature over a different message", () => {
  expectVerificationError(
    () =>
      verifySolanaSignature({
        message: `${SOL_MESSAGE}!`,
        signature: base58.encode(signSolana(SOL_MESSAGE)),
        expectedAddress: SOL_ADDRESS,
      }),
    "SIGNATURE_MISMATCH",
  );
});

Deno.test("verifySolanaSignature rejects a signature from another wallet", () => {
  const stranger = base58.encode(ed25519.getPublicKey(new Uint8Array(32).fill(8)));
  expectVerificationError(
    () =>
      verifySolanaSignature({
        message: SOL_MESSAGE,
        signature: base58.encode(signSolana(SOL_MESSAGE)),
        expectedAddress: stranger,
      }),
    "SIGNATURE_MISMATCH",
  );
});

Deno.test("verifySolanaSignature rejects signatures that are not 64 bytes", () => {
  // A 65-byte base64 signature cannot be reinterpreted as anything else.
  expectVerificationError(
    () =>
      verifySolanaSignature({
        message: SOL_MESSAGE,
        signature: toBase64(new Uint8Array(65).fill(1)),
        expectedAddress: SOL_ADDRESS,
      }),
    "INVALID_SIGNATURE_ENCODING",
  );
  // A 63-byte value is rejected too (it may surface as an encoding error or a
  // mismatch, depending on how the mis-decode lands — either way it never
  // verifies).
  assertThrows(
    () =>
      verifySolanaSignature({
        message: SOL_MESSAGE,
        signature: base58.encode(new Uint8Array(63).fill(1)),
        expectedAddress: SOL_ADDRESS,
      }),
    Web3VerificationError,
  );
});

Deno.test("verifySolanaSignature rejects garbage signatures", () => {
  expectVerificationError(
    () =>
      verifySolanaSignature({
        message: SOL_MESSAGE,
        signature: "definitely-not-a-signature",
        expectedAddress: SOL_ADDRESS,
      }),
    "INVALID_SIGNATURE_ENCODING",
  );
});
